-- ZS Retail 4.0.0: the head office's baseline (Boot 4 migration, step 1.8, decision 13).
--
-- The whole schema of a head office database at 3.1.2, as release/3.1.2's code makes it on an empty database: Hibernate 5.4's
-- create script, written by a real start of release/3.1.2 (cbae53bb) on 2026-11-10, and below it the unique indexes its
-- startup T-SQL adds (StoreErpCustomerIndex, UserBadgeCodeIndex). Compared object by object with the database that real start made: the
-- same (docs/migration/diffs/step-1.8-schema.txt). So a new database and a database upgraded from 3.1.2 start from one schema.
--
-- Flyway runs it on an empty database only. On a database at 3.1.2, which has all of it, Flyway writes a baseline marker
-- instead (spring.flyway.baseline-on-migrate) and runs the scripts after it. Frozen: never edited; a change is a new script.

create table app_release_notes (id bigint identity not null, description NVARCHAR(MAX) not null, released_at datetime2, type varchar(20) not null, version varchar(20) not null, primary key (id));
create table app_role (id bigint identity not null, active bit, created_at datetime2, created_by varchar(255), updated_at datetime2, updated_by varchar(255), is_pos_role bit not null, label varchar(255) not null, name varchar(255) not null, primary key (id));
create table app_role_permission (role_id bigint not null, permission_key varchar(255));
create table app_version (id bigint identity not null, version varchar(20) not null, primary key (id));
create table badge_scan_log (id bigint identity not null, active bit, created_at datetime2, created_by varchar(255), updated_at datetime2, updated_by varchar(255), failure_reason varchar(500), functionality varchar(255) not null, granted_by varchar(10), scan_type varchar(20) not null, scanned_badge_code varchar(50), session_id bigint, success bit not null, timestamp datetime2 not null, scanned_by_user_id bigint not null, scanned_user_id bigint, primary key (id));
